-- Etapa 6C. Compra 2017; UF do pedido SP; todos os status. Executar READ ONLY.
WITH p AS (SELECT x.*,c.dia,c.mes FROM gold.fato_pedidos x LEFT JOIN gold.dim_calendario c ON c.data_sk=x.data_compra_sk LEFT JOIN gold.dim_localizacao l ON l.localizacao_sk=x.localizacao_sk WHERE c.ano=2017 AND l.customer_state='SP'),i AS (SELECT x.*,c.dia,c.mes FROM gold.fato_itens_pedido x LEFT JOIN gold.dim_calendario c ON c.data_sk=x.data_compra_sk LEFT JOIN gold.dim_localizacao l ON l.localizacao_sk=x.localizacao_sk WHERE c.ano=2017 AND l.customer_state='SP'),g AS (SELECT x.*,c.dia,c.mes FROM gold.fato_pagamentos x LEFT JOIN gold.dim_calendario c ON c.data_sk=x.data_compra_sk LEFT JOIN gold.dim_localizacao l ON l.localizacao_sk=x.localizacao_sk WHERE c.ano=2017 AND l.customer_state='SP') SELECT (SELECT count(DISTINCT order_id) FROM p) pedidos,(SELECT count(DISTINCT order_id) FROM p WHERE order_status='delivered') delivered,(SELECT sum(price) FROM i) price,(SELECT sum(freight_value) FROM i) freight_value,(SELECT sum(payment_value) FROM g) payment_value;
